function doGet(e) {
  return ContentService.createTextOutput(JSON.stringify({
    status: "ok",
    message: "Servicio de sincronización de Evaluación Diagnóstica MINERD activo."
  })).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  try {
    var rawData = e.postData.contents;
    var data = JSON.parse(rawData);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var state = data.state;
    
    // 1. Guardar copia de seguridad en hoja "Backup_Datos"
    var backupSheet = ss.getSheetByName("Backup_Datos");
    if (!backupSheet) {
      backupSheet = ss.insertSheet("Backup_Datos");
      backupSheet.appendRow(["Fecha y Hora", "Centro Educativo", "Año Escolar", "Estado JSON Completo"]);
      backupSheet.getRange(1, 1, 1, 4).setFontWeight("bold").setBackground("#E2E8F0");
    }
    
    backupSheet.appendRow([
      new Date(),
      (state.settings && state.settings.schoolName) || "Centro Educativo",
      (state.settings && state.settings.schoolYear) || "2025-2026",
      rawData
    ]);
    
    // 2. Generar/actualizar hojas estructuradas
    actualizarHojasConsolidadas(ss, state);
    
    return ContentService.createTextOutput(JSON.stringify({ 
      status: "success", 
      message: "¡Datos sincronizados correctamente en Google Sheets!" 
    })).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ 
      status: "error", 
      error: err.toString() 
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

function actualizarHojasConsolidadas(ss, state) {
  if (!state || !state.settings) return;
  
  // Hoja: Consolidado General
  var sheetConsolidado = ss.getSheetByName("Consolidado_General");
  if (!sheetConsolidado) {
    sheetConsolidado = ss.insertSheet("Consolidado_General");
  }
  sheetConsolidado.clear();
  
  sheetConsolidado.appendRow([
    "EVALUACIÓN DIAGNÓSTICA - MINERD",
    state.settings.schoolName || "",
    "Año Escolar: " + (state.settings.schoolYear || ""),
    "Tanda: " + (state.settings.tanda || ""),
    "Distrito: " + (state.settings.district || "") + " | Regional: " + (state.settings.regional || "")
  ]);
  sheetConsolidado.getRange(1, 1, 1, 5).setFontWeight("bold").setBackground("#1E293B").setFontColor("#FFFFFF");
  
  sheetConsolidado.appendRow(["Grado", "Sección", "Docente Responsable", "Materia", "No", "Estudiante", "Valoración / Nivel", "Observaciones"]);
  sheetConsolidado.getRange(2, 1, 1, 8).setFontWeight("bold").setBackground("#CBD5E1");
  
  var sections = state.sections || [];
  sections.forEach(function(sec) {
    var students = (state.studentsBySection && state.studentsBySection[sec.id]) || [];
    var subjects = [
      { id: "lengua_espanola", label: "Lengua Española" },
      { id: "niveles_lectura", label: "Niveles de Lectura" },
      { id: "matematica", label: "Matemática" }
    ];
    
    subjects.forEach(function(sub) {
      var key = sec.grade + "_" + sec.id + "_" + sub.id;
      var evalData = state.evaluations && state.evaluations[key];
      if (evalData && evalData.evaluations) {
        students.forEach(function(st, idx) {
          var stEval = evalData.evaluations[st.id];
          if (stEval) {
            var val = "";
            if (sub.id === "niveles_lectura") {
              val = stEval.readingLevel || "Sin evaluar";
            } else {
              var scores = stEval.scores || {};
              var scoreKeys = Object.keys(scores);
              if (scoreKeys.length > 0) {
                val = scoreKeys.map(function(k) { return scores[k]; }).join(" | ");
              } else {
                val = "Sin calificar";
              }
            }
            var obs = stEval.observations || "";
            sheetConsolidado.appendRow([
              sec.grade,
              "Sección " + sec.name,
              sec.teacherName || "No asignada",
              sub.label,
              st.number || (idx + 1),
              st.name,
              val,
              obs
            ]);
          }
        });
      }
    });
  });
  
  sheetConsolidado.autoResizeColumns(1, 8);
}
